// One step of the proven rule. The step function is generated by gdp-wired's compileJs from src/kernel.ts at build
// time (dist/kernel.gen.js): the same machine the prover checked, without loading the prover in a hook.
// `stopbar verify` and the test suite regenerate it and compare it byte for byte, and replay random runs
// against gdp-wired's interpreter. There is no hand-written copy of step() anywhere.
import * as G from './kernel.gen.js'
import type {KState} from './store.ts'

export type Op = 'EDIT_CODE' | 'EDIT_TEST' | 'RUN_BUILD' | 'RUN_TESTS' | 'READ_SECRET' | 'SHELL' | 'APPROVE_TESTS' | 'APPROVE_SHELL' | 'RESUME' | 'COMMIT'
export type Req = {op: Op; cost?: number; passed?: boolean; fullSuite?: boolean; suspicious?: boolean; risky?: boolean; treeChanged?: boolean; approveRev?: number; extra?: number}
export type View = Record<string, any> & {decision: 'ALLOW' | 'BLOCK' | 'PAUSE'; halted: boolean; treeRev: number}
export type Params = {maxRetries: number; cap: number}

const DEF: Required<Req> = {op: 'EDIT_CODE', cost: 0, passed: false, fullSuite: false, suspicious: false, risky: false, treeChanged: false, approveRev: 0, extra: 0}

export const MACHINE = {name: G.MACHINE_NAME, kernelSha256: G.KERNEL_SOURCE_SHA256, machineSha256: G.MACHINE_SHA256}
if (G.MACHINE_NAME !== 'stopbar_kernel_none') throw new Error(`kernel.gen.js holds ${G.MACHINE_NAME}, not the unmutated kernel`)

export function encodeInput(r: Req): Record<string, number> {
  const req = {...DEF, ...r} as Record<string, unknown>
  const out: Record<string, number> = {}
  for (const f of G.CODEC.inputs) {
    const v = req[f.name]
    if (f.kind === 'oneOf') {
      const i = f.values!.indexOf(v as string)
      if (i < 0) throw new Error(`unknown ${f.name} ${JSON.stringify(v)}`)
      out[f.name] = i
    } else if (f.kind === 'bool') out[f.name] = v ? 1 : 0
    else {
      if (typeof v !== 'number' || !Number.isSafeInteger(v) || v < 0) throw new Error(`${f.name} must be a safe non-negative integer, got ${v}`)
      out[f.name] = v
    }
  }
  return out
}

export function decode(st: KState): View {
  const out: Record<string, unknown> = {}
  for (const f of G.CODEC.state) {
    const v = st.scalars[f.name]
    out[f.name] = f.kind === 'bool' ? v === 1 : f.kind === 'oneOf' ? f.values![v] : v
  }
  return out as View
}

export function initKernel(p: Params): KState { return G.init(p) as KState }

/** Pure step. Throws on an input outside the rule's assumptions (fail closed). */
export function kstep(p: Params, st: KState, r: Req): KState {
  return G.step(p, G.fork(st), encodeInput(r)) as KState
}
